//! The bundled HSK 3.0 curriculum (`data/hsk_curriculum.json`, generated by
//! tools/hsk-import) as the apps load it: the invariants the store and the
//! daily queue rely on, the readings the ETL's form selection exists to get
//! right, and seeding it into a fresh store.

use std::collections::HashSet;

use vocab_core::{
    curriculum::{bundled_curriculum, CurriculumIndex},
    providers::CurriculumLookup,
    store::Store,
    CurriculumItem,
};

/// Words whose first CC-CEDICT form is not their HSK reading (吧's first
/// form is the loanword `bā`, 还's the surname `Huán`, 中's the proper noun
/// `Zhōng`), or that are easy to get wrong; tools/hsk-import checks the same
/// list before it writes the file.
const SPOT_CHECKS: &[(&str, &str)] = &[
    ("吧", "ba"),
    ("了", "le"),
    ("的", "de"),
    ("还", "hái"),
    ("长", "cháng"),
    ("行", "xíng"),
    ("都", "dōu"),
    ("好", "hǎo"),
    ("要", "yào"),
    ("看", "kàn"),
    ("会", "huì"),
    ("中", "zhōng"),
    ("少", "shǎo"),
    ("大", "dà"),
    ("没", "méi"),
    ("地", "de"),
];

fn curriculum() -> Vec<CurriculumItem> {
    bundled_curriculum().expect("the bundled curriculum parses")
}

fn find<'a>(items: &'a [CurriculumItem], hanzi: &str) -> &'a CurriculumItem {
    items
        .iter()
        .find(|item| item.hanzi == hanzi)
        .unwrap_or_else(|| panic!("{hanzi} is not in the bundled curriculum"))
}

#[test]
fn it_is_the_full_hsk_3_0_word_list() {
    let items = curriculum();
    assert!(items.len() > 10_000, "only {} items", items.len());
}

#[test]
fn hanzi_are_unique_and_orders_count_up_from_zero() {
    let items = curriculum();
    let hanzi: HashSet<&str> = items.iter().map(|item| item.hanzi.as_str()).collect();
    assert_eq!(hanzi.len(), items.len(), "duplicate hanzi");
    assert!(items
        .iter()
        .all(|item| item.hanzi.trim() == item.hanzi && !item.hanzi.is_empty()));
    let orders: Vec<i64> = items.iter().map(|item| item.curriculum_order).collect();
    let expected: Vec<i64> = (0..items.len() as i64).collect();
    assert!(orders == expected, "curriculum_order is not exactly 0..n-1");
}

#[test]
fn levels_go_from_one_to_seven_and_frequency_orders_each_level() {
    let items = curriculum();
    assert!(items.iter().all(|item| (1..=7).contains(&item.hsk_level)));
    let levels: HashSet<u8> = items.iter().map(|item| item.hsk_level).collect();
    assert_eq!(
        levels.len(),
        7,
        "every level 1-6 and the 7-9 band has words"
    );
    for pair in items.windows(2) {
        let (a, b) = (&pair[0], &pair[1]);
        assert!(
            a.hsk_level <= b.hsk_level,
            "{} (level {}) before {} (level {})",
            a.hanzi,
            a.hsk_level,
            b.hanzi,
            b.hsk_level
        );
        if a.hsk_level == b.hsk_level {
            let rank = |item: &CurriculumItem| (item.frequency.is_none(), item.frequency);
            assert!(
                rank(a) <= rank(b),
                "{} ({:?}) before {} ({:?}) in level {}",
                a.hanzi,
                a.frequency,
                b.hanzi,
                b.frequency,
                a.hsk_level
            );
        }
    }
}

/// Tone-marked vowels by base vowel.
const TONED_VOWELS: &[(char, &str)] = &[
    ('a', "āáǎà"),
    ('e', "ēéěè"),
    ('i', "īíǐì"),
    ('o', "ōóǒò"),
    ('u', "ūúǔù"),
    ('ü', "ǖǘǚǜ"),
    ('ê', "ếề"),
];

/// `(base vowel, has a tone mark)` for a vowel letter, `None` otherwise.
fn vowel(c: char) -> Option<(char, bool)> {
    let lower = c.to_lowercase().next()?;
    TONED_VOWELS.iter().find_map(|&(base, toned)| {
        if lower == base {
            Some((base, false))
        } else {
            toned.contains(lower).then_some((base, true))
        }
    })
}

/// Where a syllable's tone mark belongs: on `a` or `e`, on the `o` of `ou`,
/// else on the last vowel. `None` when the syllable is right (or toneless).
fn misplaced_tone_mark(syllable: &str) -> Option<String> {
    let vowels: Vec<(usize, char, bool)> = syllable
        .chars()
        .enumerate()
        .filter_map(|(i, c)| vowel(c).map(|(base, toned)| (i, base, toned)))
        .collect();
    let marked = vowels.iter().find(|v| v.2)?.0;
    let ou = vowels
        .windows(2)
        .find(|pair| pair[0].1 == 'o' && pair[1].1 == 'u' && pair[1].0 == pair[0].0 + 1);
    let expected = vowels
        .iter()
        .find(|v| v.1 == 'a')
        .or_else(|| vowels.iter().find(|v| v.1 == 'e' || v.1 == 'ê'))
        .or(ou.map(|pair| &pair[0]))
        .or(vowels.last())?
        .0;
    (expected != marked).then(|| syllable.to_string())
}

#[test]
fn every_item_has_clean_spaced_pinyin_and_an_english_meaning() {
    for item in curriculum() {
        let pinyin = item.pinyin.as_str();
        assert!(!pinyin.trim().is_empty(), "{}: no pinyin", item.hanzi);
        assert!(
            pinyin.split(' ').all(|syllable| !syllable.is_empty()),
            "{}: pinyin {pinyin:?} is not single-space separated",
            item.hanzi
        );
        assert!(
            pinyin.chars().all(|c| c.is_alphabetic() || c == ' '),
            "{}: pinyin {pinyin:?} has leftover notation (digits, `u:`, separators)",
            item.hanzi
        );
        // One syllable per character, except that an erhua 儿 is part of the
        // syllable before it (`yī diǎnr`), never an `r` of its own.
        let characters: Vec<char> = item.hanzi.chars().collect();
        let erhua = characters.iter().skip(1).filter(|&&c| c == '儿').count();
        let syllables: Vec<&str> = pinyin.split(' ').collect();
        assert!(
            (characters.len() - erhua..=characters.len()).contains(&syllables.len()),
            "{}: pinyin {pinyin:?} is not one syllable per character",
            item.hanzi
        );
        assert!(
            !syllables.iter().any(|s| s.eq_ignore_ascii_case("r")),
            "{}: pinyin {pinyin:?} spells erhua as a syllable of its own",
            item.hanzi
        );
        let misplaced: Vec<String> = syllables
            .iter()
            .filter_map(|s| misplaced_tone_mark(s))
            .collect();
        assert!(
            misplaced.is_empty(),
            "{}: tone mark on the wrong vowel in {misplaced:?}",
            item.hanzi
        );
        let meaning = item.meaning_en.as_deref().unwrap_or_default();
        assert!(!meaning.trim().is_empty(), "{}: no meaning_en", item.hanzi);
        if let Some(german) = &item.meaning_de {
            assert!(
                !german.trim().is_empty(),
                "{}: blank meaning_de",
                item.hanzi
            );
        }
    }
}

#[test]
fn spot_check_words_have_their_hsk_reading_and_its_meanings() {
    let items = curriculum();
    for &(hanzi, pinyin) in SPOT_CHECKS {
        assert_eq!(find(&items, hanzi).pinyin, pinyin, "{hanzi}");
    }
    // The meanings belong to the chosen reading, not to the first form.
    let meaning = |hanzi| find(&items, hanzi).meaning_en.clone().unwrap_or_default();
    assert!(
        meaning("吧").starts_with("(modal particle"),
        "{}",
        meaning("吧")
    );
    assert!(meaning("还").starts_with("still"), "{}", meaning("还"));
    assert!(!meaning("还").contains("surname"), "{}", meaning("还"));
    assert!(meaning("长").contains("long"), "{}", meaning("长"));
    // Official reading up to a neutral tone (CC-CEDICT `hǎo chu`, HSK `hǎochù`).
    assert_eq!(find(&items, "好处").pinyin, "hǎo chu");
    assert!(
        meaning("好处").starts_with("benefit"),
        "{}",
        meaning("好处")
    );
    let study = find(&items, "学习");
    assert_eq!(
        (
            study.pinyin.as_str(),
            study.hsk_level,
            study.traditional.as_deref()
        ),
        ("xué xí", 1, Some("學習"))
    );
    // Repaired readings: erhua joined, a misplaced tone mark moved, a
    // heteronym inside a partly solid reading split.
    for (hanzi, pinyin) in [
        ("一点儿", "yī diǎnr"),
        ("哪儿", "nǎr"),
        ("女儿", "nǚ ér"),
        ("奥运会", "Ào yùn huì"),
        ("着眼于", "zhuó yǎn yú"),
    ] {
        assert_eq!(find(&items, hanzi).pinyin, pinyin, "{hanzi}");
    }
}

/// Upstream has one form per traditional headword and lists forms that share
/// a reading by code point, so the first is often a variant or another
/// word: 后 "empress" before 後 "behind", 当 噹 "ding dong" before 當 "to be".
/// The official list's traditional form decides.
#[test]
fn same_reading_words_have_the_official_form_and_its_meanings() {
    let items = curriculum();
    for (hanzi, traditional, meaning) in [
        ("后", "後", "behind"),
        ("当", "當", "to be"),
        ("岁", "歲", "classifier for years"),
        ("系", "系", "department"),
        ("台", "臺", "platform"),
        ("药", "藥", "medicine"),
        ("云", "雲", "cloud"),
        ("钟", "鐘", "clock"),
        ("于", "於", "(of time or place) in"),
        ("冲", "衝", "to rush"),
        ("恶心", "惡心", "nausea"),
    ] {
        let item = find(&items, hanzi);
        let meaning_en = item.meaning_en.as_deref().unwrap_or_default();
        assert_eq!(item.traditional.as_deref(), Some(traditional), "{hanzi}");
        assert!(
            meaning_en.contains(meaning),
            "{hanzi}: {meaning_en:?} lacks {meaning:?}"
        );
        assert!(
            !meaning_en.starts_with("variant of") && !meaning_en.starts_with("(onom.)"),
            "{hanzi}: {meaning_en:?}"
        );
    }
}

#[test]
fn the_dataset_has_no_example_sentences() {
    // A documented gap (data/README.md): the official dataset has none, and
    // the apkg enrichment is a local, uncommitted step. When sentences are
    // bundled, the Chinese capture test's fallback expectation changes too.
    assert!(curriculum()
        .iter()
        .all(|item| item.example_sentence_source.is_none()
            && item.vocab_audio_path.is_none()
            && item.image_path.is_none()));
}

#[test]
fn the_index_looks_up_every_word() {
    let items = curriculum();
    let index = CurriculumIndex::bundled();
    assert_eq!(index.len(), items.len());
    assert_eq!(index.lookup(" 学习 ").map(|item| item.hsk_level), Some(1));
    assert!(index.lookup("饕餮").is_none());
}

#[test]
fn it_seeds_a_fresh_store_once_and_reads_back_unchanged() {
    let items = curriculum();
    let mut store = Store::open_in_memory().unwrap();

    assert!(
        store.ensure_curriculum_seeded(&items).unwrap(),
        "first launch seeds"
    );
    assert_eq!(store.curriculum_count().unwrap(), items.len() as i64);
    assert!(
        !store.ensure_curriculum_seeded(&items).unwrap(),
        "an unchanged curriculum is not rewritten"
    );
    assert!(
        store.curriculum_in_order().unwrap() == items,
        "round trip changed items"
    );
    assert_eq!(
        store
            .get_curriculum_item("吧")
            .unwrap()
            .map(|item| item.pinyin),
        Some("ba".to_string())
    );
}
